import sailpoint.object.Identity;
        import org.apache.log4j.Logger;

        Logger log = Logger.getLogger("iiq.alpha.workflow.Alpha-WorkFlow-REHIRE");

        log.debug("Entering Workflow step: "+wfcontext.getStep().getName());
        Identity identity = (Identity) context.getObject(Identity.class, identityName);
        String action = alphaRehirerStartAuditAction;
        String targetIdentity = identity.getDisplayName();
        return createAuditEvent(wfcontext.getWorkflow().getName(), targetIdentity, action,null,null,null,null,null,null,null,null,null,null);

        import org.apache.log4j.Logger;

        import sailpoint.object.ProvisioningPlan;
        import sailpoint.object.ProvisioningPlan.AccountRequest.Operation;
        boolean changePasswordAtNextLogon = true;

        Logger log = Logger.getLogger("iiq.alpha.Alpha-WorkFlow-Rehire");
        log.debug("Alpha-Workflow-Rehire -> Entered to Build Plan Step!!!");

        ProvisioningPlan plan = new ProvisioningPlan();
        plan = buildProvisioningPlan(plan,identityName,ProvisioningPlan.AccountRequest.Operation.Enable);

        String userOU = getUserOU(identityName);
        String policyName = "Alpha-ActiveDirectory-PasswordPolicy";
        Map attributeRequestMap = new HashMap();
        attributeRequestMap.put("AC_NewParent",userOU);
        attributeRequestMap.put("password",generateNewPassword(policyName));
        attributeRequestMap.put("pwdLastSet",changePasswordAtNextLogon);


        String applicationName = "Alpha - Active Directory";

        plan = buildProvisioningPlan_Modify(plan,identityName,applicationName,"primaryAccount",attributeRequestMap);
        plan = buildProvisioningPlan_Modify(plan,identityName,applicationName,"privilegedAccount",attributeRequestMap);
        plan = buildProvisioningPlan_Modify(plan,identityName,applicationName,"secondaryAccount",attributeRequestMap);

        return plan;

Logger log = Logger.getLogger("iiq.alpha.workflow.Alpha-WorkFlow-Rehire");
Map map = getWorkflowFailures(wfcontext);
log.debug("failureMap:"+map);
if(null!=map && map.size()>0)
{
wfcontext.setVariable("alphaWorkflowFailureMap",map);
return true;
}
else
{
return false;
}

